require "rails_helper"

RSpec.describe Timekeeping::ProjectionConsumer do
  let(:projection_company) { create(:company) }
  let(:projection_project) { create(:project, client: create(:client, company: projection_company)) }
  let(:projection_user) { create(:user).tap { |user| create(:employment, company: projection_company, user:) } }

  def projection_snapshot(id:, version:, generation: 1, position: version, **fields)
    entry = TimekeepingSnapshots.entry(id:, company_id: projection_company.id, version:, project_id: projection_project.id,
                                       user_id: projection_user.id, **fields)
    TimekeepingSnapshots.item(entry, generation:, outbox_position: position)
  end

  it "applies a create and an update of one entry delivered in one batch and stores the update" do
    # While delivery is paused the outbox holds every change, so one batch can carry
    # a create and an update of the same entry; both must apply, in outbox order.
    batch = { "schema_version" => 1,
              "snapshots" => [projection_snapshot(id: 70_101, version: 1), projection_snapshot(id: 70_101, version: 2)] }

    result = described_class.call(batch:, idempotency_key: SecureRandom.uuid)

    expect(result.status).to eq(200)
    expect(result.body.deep_stringify_keys).to eq("applied" => 2, "ignored" => 0)
    stored = TimesheetEntry.find(70_101)
    expect([stored.version, stored.note, stored.company_id]).to eq([2, "v2", projection_company.id])
  end
end

RSpec.describe Timekeeping::ProjectionConsumer do
  let(:resend_company) { create(:company) }
  let(:resend_project) { create(:project, client: create(:client, company: resend_company)) }
  let(:resend_user) { create(:user).tap { |user| create(:employment, company: resend_company, user:) } }

  def resend_snapshot(id:, version:)
    entry = TimekeepingSnapshots.entry(id:, company_id: resend_company.id, version:, project_id: resend_project.id,
                                       user_id: resend_user.id)
    TimekeepingSnapshots.item(entry, generation: 1)
  end

  it "re-sending an applied batch under a new key changes no row and counts it ignored" do
    # "It upserts by entry `id` and applies a snapshot only when its `version` is higher than the row's."
    batch = { "schema_version" => 1, "snapshots" => [resend_snapshot(id: 70_201, version: 2)] }
    described_class.call(batch:, idempotency_key: SecureRandom.uuid)
    before = TimesheetEntry.find(70_201).attributes
    expect(before["version"]).to eq(2)

    resent = described_class.call(batch:, idempotency_key: SecureRandom.uuid)

    expect(resent.body.deep_stringify_keys).to eq("applied" => 0, "ignored" => 1)
    expect(TimesheetEntry.where(id: 70_201).count).to eq(1)
    expect(TimesheetEntry.find(70_201).attributes).to eq(before)
  end
end

RSpec.describe Timekeeping::ProjectionConsumer do
  let(:tombstone_company) { create(:company) }
  let(:tombstone_project) { create(:project, client: create(:client, company: tombstone_company)) }
  let(:tombstone_user) { create(:user).tap { |user| create(:employment, company: tombstone_company, user:) } }

  def tombstone_snapshot(version:, **fields)
    entry = TimekeepingSnapshots.entry(id: 70_301, company_id: tombstone_company.id, version:,
                                       project_id: tombstone_project.id, user_id: tombstone_user.id, **fields)
    TimekeepingSnapshots.batch(TimekeepingSnapshots.item(entry, generation: 1))
  end

  it "keeps a tombstone row so a late lower version cannot bring the entry back" do
    # "A discard arrives as a snapshot with `discarded_at` set (a 'tombstone'), never as a row delete."
    described_class.call(batch: tombstone_snapshot(version: 3, discarded_at: "2026-03-03T10:00:00Z"), idempotency_key: SecureRandom.uuid)

    late = described_class.call(batch: tombstone_snapshot(version: 2), idempotency_key: SecureRandom.uuid)

    expect(late.body.deep_stringify_keys).to eq("applied" => 0, "ignored" => 1)
    stored = TimesheetEntry.with_discarded.find(70_301)
    expect(stored.version).to eq(3)
    expect(stored.discarded_at).to eq(Time.utc(2026, 3, 3, 10))
    expect(TimesheetEntry.kept.where(id: 70_301)).to be_empty
  end
end

RSpec.describe Timekeeping::ProjectionConsumer do
  let(:mixed_company) { create(:company) }
  let(:mixed_project) { create(:project, client: create(:client, company: mixed_company)) }
  let(:mixed_user) { create(:user).tap { |user| create(:employment, company: mixed_company, user:) } }

  def mixed_item(id:, generation:, position:)
    entry = TimekeepingSnapshots.entry(id:, company_id: mixed_company.id, version: 1, project_id: mixed_project.id,
                                       user_id: mixed_user.id)
    TimekeepingSnapshots.item(entry, generation:, outbox_position: position)
  end

  it "writes nothing from a batch whose valid snapshots come before a stale one" do
    TimekeepingOwnership.current.update!(generation: 2)
    batch = { "schema_version" => 1, "snapshots" => [
      mixed_item(id: 70_401, generation: 2, position: 1),
      mixed_item(id: 70_402, generation: 2, position: 2),
      mixed_item(id: 70_403, generation: 1, position: 3)
    ] }

    result = described_class.call(batch:, idempotency_key: SecureRandom.uuid)

    expect(result.status).to eq(409)
    expect(result.body.deep_stringify_keys).to eq("reason" => "stale_generation")
    expect(TimesheetEntry.with_discarded.where(id: [70_401, 70_402, 70_403])).to be_empty
  end
end

RSpec.describe Timekeeping::ProjectionConsumer do
  let(:owner_company) { create(:company) }
  let(:intruder_company) { create(:company) }

  def tenant_item(company:, version:)
    project = create(:project, client: create(:client, company:))
    user = create(:user).tap { |member| create(:employment, company:, user: member) }
    entry = TimekeepingSnapshots.entry(id: 70_501, company_id: company.id, version:, project_id: project.id,
                                       user_id: user.id)
    TimekeepingSnapshots.batch(TimekeepingSnapshots.item(entry, generation: 1))
  end

  it "leaves a stored row unchanged when a higher version names another company" do
    described_class.call(batch: tenant_item(company: owner_company, version: 1), idempotency_key: SecureRandom.uuid)
    before = TimesheetEntry.find(70_501).attributes
    expect([before["company_id"], before["version"]]).to eq([owner_company.id, 1])

    # "A snapshot whose `company_id` differs from the row's is refused."
    result = described_class.call(batch: tenant_item(company: intruder_company, version: 5), idempotency_key: SecureRandom.uuid)

    expect([result.status, result.body.to_h.deep_stringify_keys]).to eq([409, { "reason" => "stale_generation" }])
    expect(result.body.to_s).not_to include(owner_company.id.to_s)
    expect(TimesheetEntry.find(70_501).attributes).to eq(before)
  end
end

RSpec.describe Timekeeping::ProjectionConsumer do
  it "accepts the previous generation through position P during a handoff and refuses it past P and after the flip" do
    company = create(:company)
    project = create(:project, client: create(:client, company:))
    user = create(:user)
    create(:employment, company:, user:)
    entry_id = 90_301
    batch = lambda do |version:, generation:, outbox_position:|
      entry = TimekeepingSnapshots.entry(id: entry_id, company_id: company.id, version:, project_id: project.id,
                                         user_id: user.id)
      TimekeepingSnapshots.batch(TimekeepingSnapshots.item(entry, generation:, outbox_position:))
    end
    deliver = lambda do |**item|
      result = described_class.call(batch: batch.call(**item), idempotency_key: nil)
      [result.status, result.body.deep_stringify_keys]
    end
    stale = [409, { "reason" => "stale_generation" }]

    TimekeepingOwnership.current.update!(generation: 2, handoff_step: "freeze", final_outbox_position: 10)

    # "During a handoff, between closing admission and the ownership flip, it also accepts the outgoing owner's
    # previous-generation snapshots, but only up to the final outbox position captured when that owner was frozen."
    expect(deliver.call(version: 1, generation: 1, outbox_position: 10)).to eq([200, { "applied" => 1, "ignored" => 0 }])
    expect(deliver.call(version: 2, generation: 1, outbox_position: 11)).to eq(stale)
    expect(TimesheetEntry.find(entry_id).version).to eq(1)

    # "The flip removes that permission."
    TimekeepingOwnership.current.update!(handoff_step: nil)
    expect(deliver.call(version: 3, generation: 1, outbox_position: 5)).to eq(stale)
    expect(TimesheetEntry.find(entry_id).version).to eq(1)

    expect(deliver.call(version: 4, generation: 2, outbox_position: 12)).to eq([200, { "applied" => 1, "ignored" => 0 }])
    expect(TimesheetEntry.find(entry_id).version).to eq(4)
  end
end
